CREATE DATABASE IF NOT EXISTS tourisme_ivoire CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tourisme_ivoire;
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS langues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(10) NOT NULL UNIQUE, nom VARCHAR(80) NOT NULL, actif BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, nom VARCHAR(80) NOT NULL, description VARCHAR(255) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS utilisateurs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(100) NOT NULL, prenom VARCHAR(100) NULL, email VARCHAR(190) NOT NULL UNIQUE, telephone VARCHAR(30) NULL, mot_de_passe_hash VARCHAR(255) NOT NULL, avatar_url VARCHAR(500) NULL, langue_id BIGINT UNSIGNED NULL, statut ENUM('actif','suspendu','en_attente') NOT NULL DEFAULT 'actif', email_verifie_at DATETIME NULL, last_login_at DATETIME NULL, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, CONSTRAINT fk_utilisateurs_langue FOREIGN KEY(langue_id) REFERENCES langues(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS utilisateurs_roles (utilisateur_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(utilisateur_id,role_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS passeports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL UNIQUE, numero VARCHAR(32) NOT NULL UNIQUE, points_total INT UNSIGNED NOT NULL DEFAULT 0, niveau SMALLINT UNSIGNED NOT NULL DEFAULT 1, date_emission DATE NOT NULL, statut ENUM('actif','suspendu') NOT NULL DEFAULT 'actif', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS parametres_utilisateurs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL UNIQUE, theme ENUM('systeme','clair','sombre') NOT NULL DEFAULT 'systeme', notifications_json JSON NULL, accessibilite_json JSON NULL, mode_hors_ligne BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS districts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(140) NOT NULL UNIQUE, code_officiel VARCHAR(30) NULL UNIQUE, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS regions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(140) NOT NULL UNIQUE, code_officiel VARCHAR(30) NULL UNIQUE, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS districts_regions (district_id BIGINT UNSIGNED NOT NULL, region_id BIGINT UNSIGNED NOT NULL, source_reference VARCHAR(500) NULL, verified_at DATETIME NULL, PRIMARY KEY(district_id,region_id), FOREIGN KEY(district_id) REFERENCES districts(id) ON DELETE CASCADE, FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS departements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, region_id BIGINT UNSIGNED NULL, district_id BIGINT UNSIGNED NULL, nom VARCHAR(120) NOT NULL, code_officiel VARCHAR(30) NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_departement_region_nom(region_id,nom), UNIQUE KEY uq_departement_district_nom(district_id,nom), KEY idx_departement_region(region_id), KEY idx_departement_district(district_id), CHECK((region_id IS NULL) <> (district_id IS NULL)), FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE RESTRICT, FOREIGN KEY(district_id) REFERENCES districts(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS localites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, departement_id BIGINT UNSIGNED NOT NULL, nom VARCHAR(140) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_localite_departement_nom(departement_id,nom), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180), FOREIGN KEY(departement_id) REFERENCES departements(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, nom VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description TEXT NULL, icone VARCHAR(80) NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', ordre SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS destinations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, localite_id BIGINT UNSIGNED NOT NULL, categorie_id BIGINT UNSIGNED NOT NULL, nom VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description TEXT NOT NULL, histoire TEXT NULL, latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, adresse VARCHAR(255) NULL, conseils_visite TEXT NULL, informations_pratiques TEXT NULL, source_reference VARCHAR(500) NULL, image_principale VARCHAR(500) NULL, statut_publication ENUM('brouillon','publie','archive') NOT NULL DEFAULT 'brouillon', is_demo BOOLEAN NOT NULL DEFAULT FALSE, published_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, KEY idx_destinations_publication(statut_publication,published_at), KEY idx_destinations_localite_categorie(localite_id,categorie_id), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180), FOREIGN KEY(localite_id) REFERENCES localites(id) ON DELETE RESTRICT, FOREIGN KEY(categorie_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS destination_categories (destination_id BIGINT UNSIGNED NOT NULL, categorie_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(destination_id,categorie_id), FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE, FOREIGN KEY(categorie_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS images_destinations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, destination_id BIGINT UNSIGNED NOT NULL, url VARCHAR(500) NOT NULL, texte_alternatif VARCHAR(255) NULL, credit VARCHAR(190) NULL, licence VARCHAR(190) NULL, ordre SMALLINT UNSIGNED NOT NULL DEFAULT 0, est_principale BOOLEAN NOT NULL DEFAULT FALSE, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_images_destination(destination_id,ordre), FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS horaires_destinations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, destination_id BIGINT UNSIGNED NOT NULL, jour_semaine TINYINT UNSIGNED NULL, ouverture TIME NULL, fermeture TIME NULL, tarif DECIMAL(12,2) NULL, devise CHAR(3) NULL, notes TEXT NULL, source_verification VARCHAR(500) NULL, verified_at DATETIME NULL, CHECK(jour_semaine IS NULL OR jour_semaine BETWEEN 1 AND 7), CHECK(tarif IS NULL OR tarif >= 0), FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS avis (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, destination_id BIGINT UNSIGNED NOT NULL, note TINYINT UNSIGNED NOT NULL, commentaire TEXT NULL, statut ENUM('en_attente','publie','rejete') NOT NULL DEFAULT 'en_attente', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, CHECK(note BETWEEN 1 AND 5), UNIQUE KEY uq_avis_utilisateur_destination(utilisateur_id,destination_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS favoris (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, destination_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_favori(utilisateur_id,destination_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS visites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, destination_id BIGINT UNSIGNED NOT NULL, visite_le DATETIME NOT NULL, source ENUM('declaration','reservation','scan') NOT NULL DEFAULT 'declaration', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_visites_utilisateur_date(utilisateur_id,visite_le), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, nom VARCHAR(100) NOT NULL, description TEXT NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transporteurs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(180) NOT NULL, description TEXT NULL, telephone VARCHAR(30) NULL, site_url VARCHAR(500) NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', is_demo BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS itineraires (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transporteur_id BIGINT UNSIGNED NULL, transport_id BIGINT UNSIGNED NOT NULL, depart_localite_id BIGINT UNSIGNED NULL, arrivee_localite_id BIGINT UNSIGNED NULL, depart_libelle VARCHAR(180) NOT NULL, arrivee_libelle VARCHAR(180) NOT NULL, duree_minutes INT UNSIGNED NULL, tarif DECIMAL(12,2) NULL, devise CHAR(3) NULL, depart_at DATETIME NULL, disponibilite ENUM('inconnue','disponible','indisponible') NOT NULL DEFAULT 'inconnue', source_verification VARCHAR(500) NULL, verified_at DATETIME NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CHECK(tarif IS NULL OR tarif >= 0), FOREIGN KEY(transporteur_id) REFERENCES transporteurs(id) ON DELETE SET NULL, FOREIGN KEY(transport_id) REFERENCES transports(id) ON DELETE RESTRICT, FOREIGN KEY(depart_localite_id) REFERENCES localites(id) ON DELETE SET NULL, FOREIGN KEY(arrivee_localite_id) REFERENCES localites(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, reference VARCHAR(40) NOT NULL UNIQUE, statut ENUM('demande','confirmee','annulee','terminee') NOT NULL DEFAULT 'demande', montant_total DECIMAL(12,2) NULL, devise CHAR(3) NULL, is_demo BOOLEAN NOT NULL DEFAULT FALSE, notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS details_reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reservation_id BIGINT UNSIGNED NOT NULL, itineraire_id BIGINT UNSIGNED NULL, quantite SMALLINT UNSIGNED NOT NULL DEFAULT 1, tarif_unitaire DECIMAL(12,2) NULL, devise CHAR(3) NULL, depart_at DATETIME NULL, statut VARCHAR(40) NOT NULL DEFAULT 'demande', libelle_snapshot VARCHAR(255) NOT NULL, is_demo BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE KEY uq_detail_reservation_libelle(reservation_id,libelle_snapshot), CHECK(quantite > 0), FOREIGN KEY(reservation_id) REFERENCES reservations(id) ON DELETE CASCADE, FOREIGN KEY(itineraire_id) REFERENCES itineraires(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS videos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, destination_id BIGINT UNSIGNED NULL, titre VARCHAR(180) NOT NULL, description TEXT NULL, media_url VARCHAR(500) NOT NULL, miniature_url VARCHAR(500) NULL, duree_secondes INT UNSIGNED NULL, autorisation_diffusion BOOLEAN NOT NULL DEFAULT FALSE, statut ENUM('en_attente','publie','rejete','archive') NOT NULL DEFAULT 'en_attente', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE RESTRICT, FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS commentaires (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, video_id BIGINT UNSIGNED NOT NULL, contenu TEXT NOT NULL, statut ENUM('publie','masque') NOT NULL DEFAULT 'publie', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME NULL, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE RESTRICT, FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS likes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, video_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_like(utilisateur_id,video_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS abonnements (abonne_id BIGINT UNSIGNED NOT NULL, suivi_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(abonne_id,suivi_id), CHECK(abonne_id <> suivi_id), FOREIGN KEY(abonne_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(suivi_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS signalements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, cible_type ENUM('video','commentaire','destination','avis') NOT NULL, cible_id BIGINT UNSIGNED NOT NULL, motif VARCHAR(100) NOT NULL, details TEXT NULL, statut ENUM('nouveau','examine','rejete','action') NOT NULL DEFAULT 'nouveau', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_signalements_cible(cible_type,cible_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quiz (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, titre VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, description TEXT NULL, theme VARCHAR(80) NOT NULL, difficulte ENUM('debutant','intermediaire','avance') NOT NULL DEFAULT 'debutant', statut ENUM('brouillon','publie','archive') NOT NULL DEFAULT 'brouillon', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quiz_id BIGINT UNSIGNED NOT NULL, enonce TEXT NOT NULL, explication TEXT NULL, ordre SMALLINT UNSIGNED NOT NULL, points SMALLINT UNSIGNED NOT NULL DEFAULT 1, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', UNIQUE KEY uq_question_ordre(quiz_id,ordre), FOREIGN KEY(quiz_id) REFERENCES quiz(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reponses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question_id BIGINT UNSIGNED NOT NULL, libelle TEXT NOT NULL, est_correcte BOOLEAN NOT NULL DEFAULT FALSE, ordre TINYINT UNSIGNED NOT NULL, UNIQUE KEY uq_reponse_ordre(question_id,ordre), FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS participations_quiz (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, quiz_id BIGINT UNSIGNED NOT NULL, score INT UNSIGNED NOT NULL DEFAULT 0, bonnes_reponses SMALLINT UNSIGNED NOT NULL DEFAULT 0, total_questions SMALLINT UNSIGNED NOT NULL DEFAULT 0, commence_at DATETIME NOT NULL, termine_at DATETIME NULL, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_participation_classement(quiz_id,score), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(quiz_id) REFERENCES quiz(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS badges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, nom VARCHAR(120) NOT NULL, description TEXT NULL, icone_url VARCHAR(500) NULL, condition_type VARCHAR(60) NOT NULL, condition_valeur INT UNSIGNED NOT NULL DEFAULT 1, points INT UNSIGNED NOT NULL DEFAULT 0, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS utilisateurs_badges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, badge_id BIGINT UNSIGNED NOT NULL, obtenu_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, is_demo BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE KEY uq_utilisateur_badge(utilisateur_id,badge_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(badge_id) REFERENCES badges(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS historique_points (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, points_delta INT NOT NULL, motif VARCHAR(120) NOT NULL, reference_type VARCHAR(40) NULL, reference_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS patrimoines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, localite_id BIGINT UNSIGNED NULL, categorie_id BIGINT UNSIGNED NULL, titre VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, contenu LONGTEXT NOT NULL, periode VARCHAR(120) NULL, statut ENUM('brouillon','publie','archive') NOT NULL DEFAULT 'brouillon', is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(localite_id) REFERENCES localites(id) ON DELETE SET NULL, FOREIGN KEY(categorie_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS consultations_patrimoine (utilisateur_id BIGINT UNSIGNED NOT NULL, patrimoine_id BIGINT UNSIGNED NOT NULL, premiere_consultation_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(utilisateur_id,patrimoine_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE, FOREIGN KEY(patrimoine_id) REFERENCES patrimoines(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medias_patrimoine (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patrimoine_id BIGINT UNSIGNED NOT NULL, type_media ENUM('image','video','audio','panorama360','modele3d') NOT NULL, url VARCHAR(500) NOT NULL, texte_alternatif VARCHAR(255) NULL, credit VARCHAR(190) NULL, licence VARCHAR(190) NULL, ordre SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(patrimoine_id) REFERENCES patrimoines(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS visites_virtuelles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, patrimoine_id BIGINT UNSIGNED NULL, destination_id BIGINT UNSIGNED NULL, titre VARCHAR(180) NOT NULL, type_visite ENUM('360','video','ar','avant_apres') NOT NULL, url VARCHAR(500) NOT NULL, fournisseur VARCHAR(120) NULL, statut ENUM('actif','inactif') NOT NULL DEFAULT 'actif', is_demo BOOLEAN NOT NULL DEFAULT FALSE, CHECK(patrimoine_id IS NOT NULL OR destination_id IS NOT NULL), FOREIGN KEY(patrimoine_id) REFERENCES patrimoines(id) ON DELETE SET NULL, FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS traductions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, langue_id BIGINT UNSIGNED NOT NULL, entite_type VARCHAR(50) NOT NULL, entite_id BIGINT UNSIGNED NOT NULL, champ VARCHAR(80) NOT NULL, contenu LONGTEXT NOT NULL, UNIQUE KEY uq_traduction(langue_id,entite_type,entite_id,champ), FOREIGN KEY(langue_id) REFERENCES langues(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, titre VARCHAR(180) NOT NULL, contenu TEXT NOT NULL, type VARCHAR(40) NOT NULL, cible_url VARCHAR(500) NULL, lu_at DATETIME NULL, is_demo BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_notifications_user_read(utilisateur_id,lu_at,created_at), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS historique_recherches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NULL, requete VARCHAR(255) NOT NULL, filtres_json JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_historique_recherche_user(utilisateur_id,created_at), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contenus_hors_ligne (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, type_contenu VARCHAR(50) NOT NULL, contenu_id BIGINT UNSIGNED NOT NULL, telecharge_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expiration_at DATETIME NULL, UNIQUE KEY uq_contenu_hors_ligne(utilisateur_id,type_contenu,contenu_id), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS historique_mot_de_passe (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, jeton_hash CHAR(64) NOT NULL UNIQUE, expire_at DATETIME NOT NULL, utilise_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS jetons_auth (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, utilisateur_id BIGINT UNSIGNED NOT NULL, jti CHAR(36) NOT NULL UNIQUE, expire_at DATETIME NOT NULL, revoque_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_jetons_auth_user(utilisateur_id,revoque_at,expire_at), FOREIGN KEY(utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tentatives_auth (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email_hash CHAR(64) NOT NULL, ip_hash CHAR(64) NOT NULL, reussie BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_auth_email_date(email_hash,created_at), KEY idx_auth_ip_date(ip_hash,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS participations_quiz_reponses (participation_id BIGINT UNSIGNED NOT NULL, question_id BIGINT UNSIGNED NOT NULL, reponse_id BIGINT UNSIGNED NOT NULL, est_correcte BOOLEAN NOT NULL, PRIMARY KEY(participation_id,question_id), FOREIGN KEY(participation_id) REFERENCES participations_quiz(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE RESTRICT, FOREIGN KEY(reponse_id) REFERENCES reponses(id) ON DELETE RESTRICT) ENGINE=InnoDB;

USE tourisme_ivoire;
CREATE FULLTEXT INDEX ft_destinations_recherche ON destinations(nom,description);
CREATE INDEX idx_videos_publication_date ON videos(statut,created_at);
CREATE INDEX idx_quiz_publication_theme ON quiz(statut,theme,difficulte);
CREATE INDEX idx_reservations_utilisateur_statut ON reservations(utilisateur_id,statut,created_at);
CREATE INDEX idx_participations_quiz_score ON participations_quiz(quiz_id,score);
CREATE INDEX idx_historique_points_user_date ON historique_points(utilisateur_id,created_at);

USE tourisme_ivoire;
CREATE OR REPLACE VIEW v_destinations_publiees AS
SELECT d.id,d.nom,d.slug,d.description,d.image_principale,d.latitude,d.longitude,
 l.nom AS localite,COALESCE(r.nom,di.nom) AS region,c.nom AS categorie,d.published_at
FROM destinations d
JOIN localites l ON l.id=d.localite_id
JOIN departements dep ON dep.id=l.departement_id
LEFT JOIN regions r ON r.id=dep.region_id
LEFT JOIN districts di ON di.id=dep.district_id
JOIN categories c ON c.id=d.categorie_id
WHERE d.statut_publication='publie' AND d.deleted_at IS NULL;

CREATE OR REPLACE VIEW v_classement_quiz AS
SELECT p.quiz_id,q.titre AS quiz,u.id AS utilisateur_id,u.nom,p.score,p.bonnes_reponses,p.total_questions,p.termine_at
FROM participations_quiz p
JOIN quiz q ON q.id=p.quiz_id
JOIN utilisateurs u ON u.id=p.utilisateur_id
WHERE p.termine_at IS NOT NULL AND q.statut='publie';
